    .{ .name = "IOR", .kind = .function, .args = "I,J", .doc = "IOR(I,J) Bitwise logical inclusive OR." },
    .{ .name = "IPARITY", .kind = .function, .args = "ARRAY,DIM=dim,MASK=mask", .doc = "IPARITY(ARRAY,DIM=dim,MASK=mask) reduces with bitwise XOR (exclusive or) the elements of ARRAY along dimension DIM if the corresponding element in MASK is TRUE." },
    .{ .name = "IRAND", .kind = .function, .args = "FLAG", .doc = "IRAND(FLAG) returns a pseudo-random number from a uniform distribution between 0 and a system-dependent limit (which is in most cases 2147483647)." },
    .{ .name = "ISATTY", .kind = .function, .args = "UNIT", .doc = "ISATTY(UNIT) Determine whether a unit is connected to a terminal device." },
    .{ .name = "ISHFT", .kind = .function, .args = "I,SHIFT", .doc = "ISHFT(I,SHIFT) returns a value corresponding to I with all of the bits shifted SHIFT places." },
    .{ .name = "ISHFTC", .kind = .function, .args = "I,SHIFT,SIZE=size", .doc = "ISHFTC(I,SHIFT,SIZE=size) returns a value corresponding to I with the rightmost SIZE bits shifted circularly SHIFT places; that is, bits shifted out one end are shifted into the opposite end." },
    .{ .name = "ISNAN", .kind = .function, .args = "X", .doc = "ISNAN(X) tests whether a floating-point value is an IEEE Not-a-Number (NaN)." },
    .{ .name = "IS_CONTIGUOUS", .kind = .function, .args = "ARRAY", .doc = "IS_CONTIGUOUS(ARRAY) tests whether an array is contiguous." },
    .{ .name = "IS_IOSTAT_END", .kind = .function, .args = "I", .doc = "IS_IOSTAT_END(I) tests whether the variable I has the value of the I/O status 'end of file'" },
    .{ .name = "IS_IOSTAT_EOR", .kind = .function, .args = "I", .doc = "IS_IOSTAT_EOR(I) tests whether the variable I has the value of the I/O status 'end of record'" },
    .{ .name = "ITIME", .kind = .subroutine, .args = "VALUES", .doc = "ITIME(VALUES) Fills VALUES with the numerical values at the current local time." },
    .{ .name = "KILL", .kind = .function, .args = "PID,STATUS=status", .doc = "KILL(PID,STATUS=status) Sends the signal specified by SIG to the process PID. See kill(2)." },
    .{ .name = "KIND", .kind = .function, .args = "X", .doc = "KIND(X) returns the kind value of the entity X." },
    .{ .name = "LBOUND", .kind = .function, .args = "ARRAY,DIM=dim,KIND=kind", .doc = "LBOUND(ARRAY,DIM=dim,KIND=kind) returns the lower bounds of an array, or a single lower bound along the DIM dimension." },
    .{ .name = "LCOBOUND", .kind = .function, .args = "COARRAY,DIM=dim,KIND=kind", .doc = "LCOBOUND(COARRAY,DIM=dim,KIND=kind) Returns the lower bounds of a coarray, or a single lower cobound along the DIM codimension." },
    .{ .name = "LEADZ", .kind = .function, .args = "I", .doc = "LEADZ(I) returns the number of leading zero bits of an integer." },
    .{ .name = "LEN", .kind = .function, .args = "STRING,KIND=kind", .doc = "LEN(STRING,KIND=kind) returns the length of a character string." },
    .{ .name = "LEN_TRIM", .kind = .function, .args = "STRING,KIND=kind", .doc = "LEN_TRIM(STRING,KIND=kind) returns the length of a character string, ignoring any trailing blanks." },
    .{ .name = "LGE", .kind = .function, .args = "STRING_A,STRING_B", .doc = "LGE(STRING_A,STRING_B) determines whether one string is lexically greater than or equal to another string." },
    .{ .name = "LGT", .kind = .function, .args = "STRING_A,STRING_B", .doc = "LGT(STRING_A,STRING_B) determines whether one string is lexically greater than another string." },
    .{ .name = "LINK", .kind = .function, .args = "PATH1,PATH2", .doc = "LINK(PATH1,PATH2) Makes a (hard) link from file PATH1 to PATH2." },
    .{ .name = "LLE", .kind = .function, .args = "STRING_A,STRING_B", .doc = "LLE(STRING_A,STRING_B) determines whether one string is lexically less than or equal to another string." },
    .{ .name = "LLT", .kind = .function, .args = "STRING_A,STRING_B", .doc = "LLT(STRING_A,STRING_B) determines whether one string is lexically less than another string." },
    .{ .name = "LNBLNK", .kind = .function, .args = "STRING", .doc = "LNBLNK(STRING) Returns the length of a character string, ignoring any trailing blanks." },
    .{ .name = "LOC", .kind = .function, .args = "X", .doc = "LOC(X) returns the address of X as an integer." },
    .{ .name = "LOG", .kind = .function, .args = "X", .doc = "LOG(X) computes the natural logarithm of X, i.e. the logarithm to the base e." },
    .{ .name = "LOG10", .kind = .function, .args = "X", .doc = "LOG10(X) computes the base 10 logarithm of X." },
    .{ .name = "LOGICAL", .kind = .function, .args = "L,KIND=kind", .doc = "LOGICAL(L,KIND=kind) Converts one kind of LOGICAL variable to another." },
    .{ .name = "LOG_GAMMA", .kind = .function, .args = "X", .doc = "LOG_GAMMA(X) computes the natural logarithm of the absolute value of the Gamma function." },
    .{ .name = "LSHIFT", .kind = .function, .args = "I,SHIFT", .doc = "LSHIFT(I,SHIFT) returns a value corresponding to I with all of the bits shifted left by SHIFT places." },
    .{ .name = "LSTAT", .kind = .function, .args = "NAME,VALUES,STATUS=status", .doc = "LSTAT(NAME,VALUES,STATUS=status) is identical to STAT, except that if path is a symbolic link, then the link itself is statted, not the file that it refers to." },
    .{ .name = "LTIME", .kind = .subroutine, .args = "TIME,VALUES", .doc = "LTIME(TIME,VALUES) Given a system time value TIME (as provided by the TIME intrinsic), fills VALUES with values extracted from it appropriate to the local time zone using localtime(3)." },
    .{ .name = "MALLOC", .kind = .function, .args = "SIZE", .doc = "MALLOC(SIZE) allocates SIZE bytes of dynamic memory and returns the address of the allocated memory." },
    .{ .name = "MASKL", .kind = .function, .args = "I,KIND=kind", .doc = "MASKL(I,KIND=kind) has its leftmost I bits set to 1, and the remaining bits set to 0." },
    .{ .name = "MASKR", .kind = .function, .args = "I,KIND=kind", .doc = "MASKR(I,KIND=kind) has its rightmost I bits set to 1, and the remaining bits set to 0." },
    .{ .name = "MATMUL", .kind = .function, .args = "MATRIX_A,MATRIX_B", .doc = "MATMUL(MATRIX_A,MATRIX_B) performs a matrix multiplication on numeric or logical arguments." },
    .{ .name = "MAX", .kind = .function, .args = "A1,A2", .doc = "MAX(A1,A2,...) returns the argument with the largest (most positive) value." },
    .{ .name = "MAXEXPONENT", .kind = .function, .args = "X", .doc = "MAXEXPONENT(X) returns the maximum exponent in the model of the type of X." },
    .{ .name = "MAXLOC", .kind = .function, .args = "ARRAY,DIM=dim,MASK=mask,KIND=kind,BACK=back", .doc = "MAXLOC(ARRAY,DIM=dim,MASK=mask,KIND=kind,BACK=back) determines the location of the element in the array with the maximum value." },
    .{ .name = "MAXVAL", .kind = .function, .args = "ARRAY,DIM=dim,MASK=mask,KIND=kind,BACK=back", .doc = "MAXVAL(ARRAY,DIM=dim,MASK=mask) determines the maximum value of the elements in an array." },
    .{ .name = "MCLOCK", .kind = .function, .doc = "MCLOCK() Returns the number of clock ticks since the start of the process, based on the function clock(3) in the C standard library." },
    .{ .name = "MCLOCK8", .kind = .function, .doc = "MCLOCK8() Returns the number of clock ticks since the start of the process, based on the function clock(3) in the C standard library." },
    .{ .name = "MERGE", .kind = .function, .args = "TSOURCE,FSOURCE,MASK", .doc = "MERGE(TSOURCE,FSOURCE,MASK) select values from two arrays according to a logical mask." },
    .{ .name = "MERGE_BITS", .kind = .function, .args = "I,J,MASK", .doc = "MERGE_BITS(I,J,MASK) merges the bits of I and J as determined by the mask." },
    .{ .name = "MIN", .kind = .function, .args = "A1,A2", .doc = "MIN(A1,A2,...) returns the argument with the smallest (most negative) value." },
    .{ .name = "MINEXPONENT", .kind = .function, .args = "X", .doc = "MINEXPONENT(X) returns the minimum exponent in the model of the type of X." },
    .{ .name = "MINLOC", .kind = .function, .args = "ARRAY,DIM=dim,MASK=mask,KIND=kind,BACK=back", .doc = "MINLOC(ARRAY,DIM=dim,MASK=mask,KIND=kind,BACK=back) determines the location of the element in the array with the minimum value." },
    .{ .name = "MINVAL", .kind = .function, .args = "ARRAY,DIM=dim,MASK=mask,KIND=kind,BACK=back", .doc = "MINVAL(ARRAY,DIM=dim,MASK=mask) determines the minimum value of the elements in an array." },
    .{ .name = "MOD", .kind = .function, .args = "A,P", .doc = "MOD(A,P) computes the remainder of the division of A by P." },
    .{ .name = "MODULO", .kind = .function, .args = "A,P", .doc = "MODULO(A,P) computes the A modulo P." },
    .{ .name = "MOVE_ALLOC", .kind = .function, .args = "FROM,TO", .doc = "MOVE_ALLOC(FROM,TO) moves the allocation from FROM to TO." },
    .{ .name = "MVBITS", .kind = .function, .args = "FROM,TO", .doc = "MVBITS(FROM,FROMPOS,LEN,TO,TOPOS) moves LEN bits from positions FROMPOS through FROMPOS+LEN-1 of FROM to positions TOPOS through TOPOS+LEN-1 of TO." },
    .{ .name = "NEAREST", .kind = .function, .args = "X,S", .doc = "NEAREST(X,S) returns the processor-representable number nearest to X in the direction indicated by the sign of S." },
    .{ .name = "NEW_LINE", .kind = .function, .args = "C", .doc = "NEW_LINE(C) returns the new-line character." },
    .{ .name = "NINT", .kind = .function, .args = "A,KIND=kind", .doc = "NINT(A,KIND=kind) rounds its argument to the nearest whole number." },
    .{ .name = "NORM2", .kind = .function, .args = "ARRAY,DIM=dim", .doc = "NORM2(ARRAY,DIM=dim) Calculates the Euclidean vector norm (L_2 norm) of ARRAY along dimension DIM." },
    .{ .name = "NOT", .kind = .function, .args = "I", .doc = "NOT(I) returns the bitwise Boolean inverse of I." },
    .{ .name = "NULL", .kind = .function, .doc = "NULL() returns a disassociated pointer." },
    .{ .name = "PACK", .kind = .function, .args = "ARRAY,MASK=mask,VECTOR=vector", .doc = "PACK(ARRAY,MASK=mask,VECTOR=vector) stores the elements of ARRAY in an array of rank one." },
    .{ .name = "PARITY", .kind = .function, .args = "MASK,DIM=dim", .doc = "PARITY(MASK,DIM=dim) Calculates the parity, i.e. the reduction using .XOR., of MASK along dimension DIM." },
    .{ .name = "PERROR", .kind = .subroutine, .args = "STRING", .doc = "PERROR(STRING) Prints (on the C stderr stream) a newline-terminated error message corresponding to the last system error. This is prefixed by STRING, a colon and a space." },
    .{ .name = "POPCNT", .kind = .function, .args = "I", .doc = "POPCNT(I) returns the number of bits set (’1’ bits) in the binary representation of I." },
    .{ .name = "POPPAR", .kind = .function, .args = "I", .doc = "POPPAR(I) returns parity of the integer I, i.e. the parity of the number of bits set ('1' bits) in the binary representation of I. It is equal to 0 if I has an even number of bits set, and 1 for an odd number of '1' bits." },
    .{ .name = "PRECISION", .kind = .function, .args = "X", .doc = "PRECISION(X) returns the decimal precision in the model of the type of X." },
    .{ .name = "PRESENT", .kind = .function, .args = "A", .doc = "PRESENT(A) determines whether an optional dummy argument is present." },
    .{ .name = "PRODUCT", .kind = .function, .args = "ARRAY,DIM=dim,MASK=mask", .doc = "PRODUCT(ARRAY,DIM=dim,MASK=mask) multiplies the elements of ARRAY along dimension DIM if the corresponding element in MASK is TRUE." },
    .{ .name = "RADIX", .kind = .function, .args = "X", .doc = "RADIX(X) returns the base of the model representing the entity X." },
    .{ .name = "RAN", .kind = .function, .args = "I", .doc = "RAN(I) For compatibility with HP FORTRAN 77/iX, the RAN intrinsic is provided as an alias for RAND." },
    .{ .name = "RAND", .kind = .function, .args = "I", .doc = "RAND(I) returns a pseudo-random number from a uniform distribution between 0 and 1." },
    .{ .name = "RANDOM_INIT", .kind = .subroutine, .args = "REPEATABLE,IMAGE_DISTINCT", .doc = "RANDOM_INIT(REPEATABLE,IMAGE_DISTINCT) Initializes the state of the pseudorandom number generator used by RANDOM_NUMBER." },
    .{ .name = "RANDOM_NUMBER", .kind = .subroutine, .args = "HARVEST", .doc = "RANDOM_NUMBER(HARVEST) returns a single pseudorandom number or an array of pseudorandom numbers." },
    .{ .name = "RANDOM_SEED", .kind = .subroutine, .args = "SIZE=size,PUT=put,GET=get", .doc = "RANDOM_SEED(SIZE=size,PUT=put,GET=get) restarts or queries the state of the pseudorandom number generator used by RANDOM_NUMBER." },
    .{ .name = "RANGE", .kind = .function, .args = "X", .doc = "RANGE(X) returns the decimal exponent range in the model of the type of X." },
    .{ .name = "RANK", .kind = .function, .args = "A", .doc = "RANK(A) returns the rank of a scalar or array data object." },
    .{ .name = "REAL", .kind = .function, .args = "A,KIND=kind", .doc = "REAL(A,KIND=kind) converts its argument A to a real type." },
    .{ .name = "RENAME", .kind = .function, .args = "PATH1,PATH2", .doc = "RENAME(PATH1,PATH2) Renames a file from file PATH1 to PATH2." },
    .{ .name = "REPEAT", .kind = .function, .args = "STRING,NCOPIES", .doc = "REPEAT(STRING,NCOPIES) concatenates NCOPIES copies of a string." },
    .{ .name = "RESHAPE", .kind = .function, .args = "SOURCE,SHAPE,PAD=pad,ORDER=order", .doc = "RESHAPE(SOURCE,SHAPE,PAD=pad,ORDER=order) reshapes SOURCE to correspond to SHAPE." },
    .{ .name = "RRSPACING", .kind = .function, .args = "X", .doc = "RRSPACING(X) returns the reciprocal of the relative spacing of model numbers near X." },
    .{ .name = "RSHIFT", .kind = .function, .args = "I,SHIFT", .doc = "RSHIFT(I,SHIFT) returns a value corresponding to I with all of the bits shifted right by SHIFT places." },
    .{ .name = "SAME_TYPE_AS", .kind = .function, .args = "A,B", .doc = "SAME_TYPE_AS(A,B) query dynamic types for equality." },
    .{ .name = "SCALE", .kind = .function, .args = "X,I", .doc = "SCALE(X,I) returns X * RADIX(X)**I." },
    .{ .name = "SCAN", .kind = .function, .args = "STRING,SET,BACK=back,KIND=kind", .doc = "SCAN(STRING,SET,BACK=back,KIND=kind) scans a STRING for any of the characters in a SET of characters." },
    .{ .name = "SECNDS", .kind = .function, .args = "X", .doc = "SECNDS(X) gets the time in seconds from the real-time system clock." },
    .{ .name = "SECOND", .kind = .function, .args = "TIME", .doc = "SECOND(TIME) Returns a REAL(4) value representing the elapsed CPU time in seconds." },
    .{ .name = "SELECTED_CHAR_KIND", .kind = .function, .args = "NAME", .doc = "SELECTED_CHAR_KIND(NAME) returns the kind value for the character set named NAME, if a character set with such a name is supported, or -1 otherwise." },
    .{ .name = "SELECTED_INT_KIND", .kind = .function, .args = "R", .doc = "SELECTED_INT_KIND(R) return the kind value of the smallest integer type that can represent all values ranging from -10^R (exclusive) to 10^R (exclusive)." },
    .{ .name = "SELECTED_REAL_KIND", .kind = .function, .args = "P,R", .doc = "SELECTED_REAL_KIND(P,R) returns the kind value of a real data type with decimal precision of at least P digits, exponent range of at least R, and with a radix of RADIX." },
    .{ .name = "SET_EXPONENT", .kind = .function, .args = "X,I", .doc = "SET_EXPONENT(X,I) returns the real number whose fractional part is that that of X and whose exponent part is I." },
    .{ .name = "SHAPE", .kind = .function, .args = "SOURCE,KIND=kind", .doc = "SHAPE(SOURCE,KIND=kind) determines the shape of an array." },
    .{ .name = "SHIFTA", .kind = .function, .args = "I,SHIFT", .doc = "SHIFTA(I,SHIFT) returns a value corresponding to I with all of the bits shifted right by SHIFT places." },
    .{ .name = "SHIFTL", .kind = .function, .args = "I,SHIFT", .doc = "SHIFTL(I,SHIFT) returns a value corresponding to I with all of the bits shifted left by SHIFT places." },
    .{ .name = "SHIFTR", .kind = .function, .args = "I,SHIFT", .doc = "SHIFTR(I,SHIFT) returns a value corresponding to I with all of the bits shifted right by SHIFT places." },
    .{ .name = "SIGN", .kind = .function, .args = "A,B", .doc = "SIGN(A,B) returns the value of A with the sign of B." },
    .{ .name = "SIGNAL", .kind = .function, .args = "NUMBER,HANDLER", .doc = "SIGNAL(NUMBER,HANDLER) causes external subroutine HANDLER to be executed with a single integer argument when signal NUMBER occurs." },
    .{ .name = "SIN", .kind = .function, .args = "X", .doc = "SIN(X) computes the sine of X." },
    .{ .name = "SIND", .kind = .function, .args = "X", .doc = "SIND(X) computes the sine of X in degrees." },
    .{ .name = "SINH", .kind = .function, .args = "X", .doc = "SINH(X) computes the hyperbolic sine of X." },
    .{ .name = "SIZE", .kind = .function, .args = "ARRAY,DIM=dim,KIND=kind", .doc = "SIZE(ARRAY,DIM=dim,KIND=kind) determines the extent of ARRAY along a specified dimension DIM, or the total number of elements in ARRAY if DIM is absent." },
    .{ .name = "SIZEOF", .kind = .function, .args = "X", .doc = "SIZEOF(X) calculates the number of bytes of storage the expression X occupies." },
    .{ .name = "SLEEP", .kind = .subroutine, .args = "SECONDS", .doc = "SLEEP(SECONDS) Calling this subroutine causes the process to pause for SECONDS seconds." },
    .{ .name = "SPACING", .kind = .function, .args = "X", .doc = "SPACING(X) determines the distance between the argument X and the nearest adjacent number of the same type." },
    .{ .name = "SPREAD", .kind = .function, .args = "SOURCE,DIM,NCOPIES", .doc = "SPREAD(SOURCE,DIM,NCOPIES) replicates a SOURCE array NCOPIES times along a specified dimension DIM." },
    .{ .name = "SQRT", .kind = .function, .args = "X", .doc = "SQRT(X) computes the square root of X." },
    .{ .name = "SRAND", .kind = .subroutine, .args = "SEED", .doc = "SRAND(SEED) reinitializes the pseudo-random number generator called by RAND and IRAND." },
    .{ .name = "STAT", .kind = .function, .args = "NAME,VALUES", .doc = "STAT(NAME,VALUES) This function returns information about a file." },
    .{ .name = "STORAGE_SIZE", .kind = .function, .args = "A,KIND=kind", .doc = "STORAGE_SIZE(A,KIND=kind) Returns the storage size of argument A in bits." },
    .{ .name = "SUM", .kind = .function, .args = "ARRAY,DIM=dim,MASK=mask", .doc = "SUM(ARRAY,DIM=dim,MASK=mask) adds the elements of ARRAY along dimension DIM if the corresponding element in MASK is TRUE." },
    .{ .name = "SYMLNK", .kind = .function, .args = "PATH1,PATH2", .doc = "SYMLNK(PATH1,PATH2) Makes a symbolic link from file PATH1 to PATH2." },
    .{ .name = "SYSTEM", .kind = .function, .args = "COMMAND,STATUS=status", .doc = "SYSTEM(COMMAND,STATUS=status) Passes the command COMMAND to a shell (see system(3))." },
    .{ .name = "SYSTEM_CLOCK", .kind = .function, .args = "COUNT=count,COUNT_RATE=count_rate,COUNT_MAX=count_max", .doc = "SYSTEM_CLOCK(COUNT=count,COUNT_RATE=count_rate,COUNT_MAX=count_max) determines the COUNT of a processor clock since an unspecified time in the past modulo COUNT_MAX, COUNT_RATE determines the number of clock ticks per second." },
    .{ .name = "TAN", .kind = .function, .args = "X", .doc = "TAN(X) computes the tangent of X." },
    .{ .name = "TAND", .kind = .function, .args = "X", .doc = "TAND(X) computes the tangent of X in degrees." },
    .{ .name = "TANH", .kind = .function, .args = "X", .doc = "TANH(X) computes the hyperbolic tangent of X." },
    .{ .name = "THIS_IMAGE", .kind = .function, .args = "DISTANCE=distance|COARRAY,DIM=dim", .doc = "THIS_IMAGE(DISTANCE=distance|COARRAY,DIM=dim) Returns the cosubscript for this image." },
    .{ .name = "TIME", .kind = .function, .doc = "TIME() Returns the current time encoded as an integer." },
    .{ .name = "TIME8", .kind = .function, .doc = "TIME8() Returns the current time encoded as an integer. This value is suitable for passing to CTIME, GMTIME, and LTIME." },
    .{ .name = "TINY", .kind = .function, .args = "X", .doc = "TINY(X) returns the smallest positive (non zero) number in the model of the type of X." },
    .{ .name = "TRAILZ", .kind = .function, .args = "I", .doc = "TRAILZ(I) returns the number of trailing zero bits of an integer." },
    .{ .name = "TRANSFER", .kind = .function, .args = "SOURCE,MOLD,SIZE=size", .doc = "TRANSFER(SOURCE,MOLD,SIZE=size) interprets the bitwise representation of SOURCE in memory as if it is the representation of a variable or array of the same type and type parameters as MOLD." },
    .{ .name = "TRANSPOSE", .kind = .function, .args = "MATRIX", .doc = "TRANSPOSE(MATRIX) transpose an array of rank two." },
    .{ .name = "TRIM", .kind = .function, .args = "STRING", .doc = "TRIM(STRING) removes trailing blank characters of a string." },
    .{ .name = "TTYNAM", .kind = .function, .args = "UNIT", .doc = "TTYNAM(UNIT) Get the name of a terminal device." },
    .{ .name = "UBOUND", .kind = .function, .args = "ARRAY,DIM=dim,KIND=kind", .doc = "UBOUND(ARRAY,DIM=dim,KIND=kind) returns the upper bounds of an array, or a single upper bound along the DIM dimension." },
    .{ .name = "UCOBOUND", .kind = .function, .args = "ARRAY,DIM=dim,KIND=kind", .doc = "UCOBOUND(ARRAY,DIM=dim,KIND=kind) Returns the upper cobounds of a coarray, or a single upper cobound along the DIM codimension." },
    .{ .name = "UMASK", .kind = .function, .args = "MASK", .doc = "UMASK(MASK) Sets the file creation mask to MASK." },
    .{ .name = "UNLINK", .kind = .function, .args = "PATH", .doc = "UNLINK(PATH) Unlinks the file PATH." },
    .{ .name = "UNPACK", .kind = .function, .args = "VECTOR,MASK,FIELD", .doc = "UNPACK(VECTOR,MASK,FIELD) Store the elements of VECTOR in an array of higher rank." },
    .{ .name = "VERIFY", .kind = .function, .args = "STRING,SET,BACK=back,KIND=kind", .doc = "VERIFY(STRING,SET,BACK=back,KIND=kind) verifies that all the characters in STRING belong to the set of characters in SET." },
    .{ .name = "XOR", .kind = .function, .args = "I,J", .doc = "XOR(I,J) Bitwise logical exclusive or." },
};
